            sym.funcname = getStr(funcnameptr);
        }
        sym.libbase = getU64(dlinfo.add(8));
        sym.funcoff = npaddr.sub(getPt(dlinfo.add(24)));
    }
    if (sym.libname == "unknown" || sym.funcname == "unknown") {
