// Export function: check all loaded module consistence with file
/**
	nfilter : null for all modules, "libc.so" for libc.so
	mask : 0x1 for .rodata,  0x2 for .text,  0x4 for .got,  0x8 for .plt.got
*/
var global_symbols = new Array();
var modules = null;

function checkConsistency(nfilter, mask) {
    if (modules == null) {
        modules = getAllModules();
    }
    if (global_symbols.length == 0) {
        for (var i = 0; i < modules.length; i++) {
            // modules address/name/type
            var tp = modules[i].path.split("/");
            var path = tp[tp.length - 1];
            var modsym = Module.enumerateExportsSync(path);
            var modbase = new Object();
            modbase.address = modules[i].vmmin;
            modbase.name = "unknown";
            modbase.type = "modbase";
            modsym.push(modbase);
            modsym.sort(function(v1, v2) {
                return v1.address - v2.address;
            });
            for (var j = 0; j < modsym.length; j++) {
                modsym[j].path = path;
            }
            global_symbols = global_symbols.concat(modsym);
        }
    }

    for (var i = 0; i < modules.length; i++) {
        if (nfilter == null || modules[i].path.indexOf(nfilter) != -1) {
            if (getElfData(modules[i])) {
                compareMemory(modules[i], mask);
            }
        }
    }
}

function dumpModule(name) {
	if (modules == null) {
		modules = getAllModules();
	}
	var modindx = -1;
    for (var i = 0; i < modules.length; i++) {
        if (modules[i].path.indexOf(name) != -1) {
			// Get file name
			modindx = i;
			break;
        }
    }
	if (modindx != -1) {
		var filepath = modules[modindx].path;
		var tp = filepath.split("/");
		var filename = tp[tp.length - 1];
		var textindx = -1;
		var sections = null;	
		if (getElfData(modules[modindx])) {
			// Recover .text section
			sections = modules[modindx].sections;
			for (var j = 0; j < sections.length; j++) {
				if (sections[j].name == ".text") {
					textindx = j;
					break;
				}
			}
		}
		var newpath = "/sdcard/" + filename;
		getCommandOutput("cp " + filepath + " " + newpath);
		var fmodule = open(newpath, O_WRONLY, 0);
		if (textindx != -1 && fmodule != -1) {
			console.log("write " + newpath + " file->mem " + sections[textindx].fileoff.toString(16) + "->" + sections[textindx].memaddr.toString(16) + " size:" + sections[textindx].size.toString(16));
			lseek(fmodule, sections[textindx].fileoff, SEEK_SET); 
			write(fmodule, ptr(sections[textindx].memaddr), sections[textindx].size);
			close(fmodule);
		}	
	}
}

'use strict';

// ==================================================
// CONFIG — EDIT THESE
// ==================================================
const GAME_PACKAGE = "com.supercell.brawlstars";
const GAME_LIB = "libg.so";

// Native function names in YOUR game
const FN_GET_PLAYER_POS = "getPlayerPosition";
const FN_SET_PLAYER_POS = "setPlayerPosition";
const FN_PROJECTILE_UPD = "updateProjectile";
const FN_GAME_TICK = "gameUpdate";

// Dodge behavior
const HIT_RADIUS = 2.0;
const DODGE_DISTANCE = 3.5;
const SMOOTH_STEPS = 6;
const PREDICT_TIME = 0.25;

// ==================================================
// STATE
// ==================================================
let player = {
    x: 0,
    y: 0
};
let projectiles = [];
let dodgeCooldown = false;

// ==================================================
// MATH
// ==================================================
function dist(ax, ay, bx, by) {
    const dx = ax - bx;
    const dy = ay - by;
    return Math.sqrt(dx * dx + dy * dy);
}

function normalize(x, y) {
    const len = Math.sqrt(x * x + y * y) || 1;
    return {
        x: x / len,
        y: y / len
    };
}

// ==================================================
// PLAYER POSITION HOOK
// ==================================================
Interceptor.attach(
    Module.findExportByName(GAME_LIB, FN_GET_PLAYER_POS), {
        onEnter(args) {
            this.xPtr = args[0];
            this.yPtr = args[1];
        },
        onLeave() {
            player.x = this.xPtr.readFloat();
            player.y = this.yPtr.readFloat();
        }
    }
);

// ==================================================
// PROJECTILE TRACKING
// ==================================================
Interceptor.attach(
    Module.findExportByName(GAME_LIB, FN_PROJECTILE_UPD), {
        onEnter(args) {
            projectiles.push({
                x: args[0].toFloat(),
                y: args[1].toFloat(),
                vx: args[2].toFloat(),
                vy: args[3].toFloat()
            });
        }
    }
);

// ==================================================
// GAME TICK — DECISION POINT
// ==================================================
Interceptor.attach(
    Module.findExportByName(GAME_LIB, FN_GAME_TICK), {
        onEnter() {
            if (dodgeCooldown) return;

            for (let p of projectiles) {
                const fx = p.x + p.vx * PREDICT_TIME;
                const fy = p.y + p.vy * PREDICT_TIME;

                if (dist(player.x, player.y, fx, fy) < HIT_RADIUS) {
                    dodgeAwayFrom(p);
                    break;
                }
            }

            projectiles.length = 0;
        }
    }
);

// ==================================================
// SMOOTH MULTI-DIRECTION DODGE
// ==================================================
function dodgeAwayFrom(p) {
    dodgeCooldown = true;

    // Perpendicular dodge vector
    const dx = player.x - p.x;
    const dy = player.y - p.y;
    const dir = normalize(-dy, dx);

    const targetX = player.x + dir.x * DODGE_DISTANCE;
    const targetY = player.y + dir.y * DODGE_DISTANCE;

    const setPos = new NativeFunction(
        Module.findExportByName(GAME_LIB, FN_SET_PLAYER_POS),
        'void', ['float', 'float']
    );

    let step = 0;
    const startX = player.x;
    const startY = player.y;

    const timer = setInterval(() => {
        step++;
        const t = step / SMOOTH_STEPS;

        const nx = startX + (targetX - startX) * t;
        const ny = startY + (targetY - startY) * t;

        setPos(nx, ny);

        if (step >= SMOOTH_STEPS) {
            clearInterval(timer);
            setTimeout(() => dodgeCooldown = false, 200);
        }
    }, 16); // ~60 FPS
}

